package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

// gsrWitnessConflictStorage embeds storage.Client so it satisfies the interface
// regardless of any methods not used by Store.Mutate. ReadFile reports a missing
// object (ignoring ctx on purpose) and WriteFile always reports an ETag conflict.
type gsrWitnessConflictStorage struct {
	storage.Client
	writes int
}

func (f *gsrWitnessConflictStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	return nil, "", storage.ErrNotFound
}

func (f *gsrWitnessConflictStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	fake := &gsrWitnessConflictStorage{}
	s := &Store{Storage: fake, Bucket: "bucket"}

	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, _ = s.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact { return c })

	if fake.writes >= maxWriteRetries {
		t.Fatalf("Mutate with an already-cancelled context made %d WriteFile attempts, want fewer than %d", fake.writes, maxWriteRetries)
	}
}
